374: function applyMove(attacker, defender, move, done) {
375:   if(!battle||battle.finished)return
376:   const status=battle.status[attacker]
377:   if(status.staggered) {
378:     status.staggered=false
379:     battle.guard[attacker]=false
380:     battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+8)
381:     toast(`${battle[attacker].name} is staggered and loses the turn.`)
382:     done(); return
383:   }
384:   if(move.type==='defend') {
385:     battle.guard[attacker]=true; battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+Math.abs(move.cost));
386:     toast(`${battle[attacker].name} braces and recovers stamina.`); done(); return
387:   }
388:   const cost=Math.max(0,move.cost)
389:   if(battle.sta[attacker]<cost) { battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+12); toast(`${battle[attacker].name} is winded and recovers 12 stamina.`); done(); return }
390:   battle.sta[attacker]-=cost
391:   const accuracy=Math.max(0.1,move.acc-(status.accuracyDown?0.25:0))
392:   status.accuracyDown=false
393:   if(Math.random()>accuracy) { toast(`${move.name} missed!`); done(); return }
394:   const roadScale=attacker==='foe'&&battle.challenge?(1+(battle.challenge.level-1)*0.022+(battle.challenge.boss?0.28:0)):1
