217: function contractProgress(contract, genome) {
218:   const ratios = contract.goals.map(([key, target]) => Math.min(1, ((genome?.[key] || [0.5, 0.5]).reduce((sum, allele) => sum + Number(allele || 0), 0) / 2) / target))
219:   const percent = Math.round(ratios.reduce((sum, ratio) => sum + ratio, 0) / ratios.length * 100)
220:   return { percent, complete: ratios.every(ratio => ratio >= 1) }
221: }
